@Override
    public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        if (playerMagicData.getAdditionalCastData() instanceof TargetEntityCastData targetingData) {
            var targetEntity = targetingData.getTarget((ServerLevel) world);
            WispEntity wispEntity = new WispEntity(world, entity, getSpellPower(spellLevel, entity));
            wispEntity.setTarget(targetEntity);
            wispEntity.setPos(Utils.getPositionFromEntityLookDirection(entity, 2).subtract(0, .2, 0));
            world.addFreshEntity(wispEntity);
        }
        super.onCast(world, spellLevel, entity, castSource, playerMagicData);
    }

@Override
    public boolean checkPreCastConditions(Level level, int spellLevel, LivingEntity entity, MagicData playerMagicData) {
        return Utils.preCastTargetHelper(level, entity, playerMagicData, this, 48, .35f);
    }

public boolean canUse() {
        var livingentity = this.wisp.getTarget();
        if (livingentity != null && livingentity.isAlive()) {
            this.target = livingentity;
            //irons_spellbooks.LOGGER.debug("WizardAttackGoal.canuse: target:{}", target.getName().getString());
            return true;
        } else {
            return false;
        }
    }

public boolean canContinueToUse() {
        return this.canUse() || this.target.isAlive() && !this.wisp.getNavigation().isDone();
    }

public void stop() {
        this.target = null;
    }

public void tick() {
        double distanceSquared = this.target.distanceToSqr(this.target.getX(), this.target.getY(), this.target.getZ());
        boolean hasLineOfSight = this.wisp.getSensing().hasLineOfSight(this.target);
        var moveResult = this.wisp.getNavigation().moveTo(target.getX(), target.getY(), target.getZ(), this.speedModifier);

        //irons_spellbooks.LOGGER.debug("WispAttackGoal.tick: moveResult:{}, hasLineOfSight:{}", moveResult, hasLineOfSight);

        this.wisp.getLookControl().setLookAt(this.target, 180, 180);
    }

public boolean hurt(DamageSource pSource, float pAmount) {
        if (!this.level.isClientSide) {
            this.popAndDie();
        }

        return true;
    }

private void popAndDie() {
        this.playSound(SoundEvents.SHULKER_BULLET_HURT, 1.0F, 1.0F);
        ((ServerLevel) this.level).sendParticles(ParticleTypes.CRIT, this.getX(), this.getY(), this.getZ(), 15, 0.2D, 0.2D, 0.2D, 0.0D);
        this.discard();
    }

@Override
    protected void customServerAiStep() {
        if (this.cachedOwner == null || !this.cachedOwner.isAlive()) {
            this.discard();
        }
    }

@Override
    protected void customServerAiStep() {
        super.customServerAiStep();

        LivingEntity target = getTarget();
        if (target != null) {
            this.navigation.moveTo(target, 7);
            //this.moveControl.setWantedPosition(target.getX(), target.getY(), target.getZ(), 5);
        }
        if (this.tickCount % 8 == 0) {
            if (level.collidesWithSuffocatingBlock(this, this.getBoundingBox().move(0, -1, 0))) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, 0.02, 0));
            } else {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -0.008, 0));
            }
        }
        if (!this.moveControl.hasWanted()) {
            this.setDeltaMovement(this.getDeltaMovement().multiply(.95f, 1, .95f));
        }
        if ((this.tickCount % 7) == 0) {
            float fade = 1 - Mth.clamp((tickCount - maxLife + 40) / (float) (maxLife), 0, 1f);
            this.playSound(SoundRegistry.FIREFLY_SWARM_IDLE.get(), .25f * fade, .95f + Utils.random.nextFloat() * .1f);
        }
        if (this.tickCount % 15 == 0) {
            //Damage tick
            float inflate = radius - this.getBbWidth() * .5f;
            this.level.getEntities(this, this.getBoundingBox().inflate(inflate), this::canHitEntity).forEach(
                    (entity) -> {
                        if (canHitEntity(entity)) {
                            boolean hit = DamageSources.applyDamage(entity, damage, SpellRegistry.FIREFLY_SWARM_SPELL.get().getDamageSource(this, getOwner()));
                            if (hit) {
                                this.playSound(SoundRegistry.FIREFLY_SWARM_ATTACK.get(), .75f, .9f + Utils.random.nextFloat() * .2f);
                                if (target == null) {
                                    setTarget(entity);
                                } else if (target != entity) {
                                    nextTarget = entity;
                                }
                            }
                        }
                    }
            );
            if (getTarget() == null || getTarget().isDeadOrDying()) {
                setTarget(nextTarget);
                if (nextTarget != null && nextTarget.isRemoved()) {
                    nextTarget = null;
                }
            }
        }
    }

@Override
    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        Vec3 spawn = null;
        Entity target = null;

        if (playerMagicData.getAdditionalCastData() instanceof TargetEntityCastData castTargetingData) {
            spawn = castTargetingData.getTargetPosition((ServerLevel) level);
            target = castTargetingData.getTarget((ServerLevel) level);
        }
        if (spawn == null) {
            HitResult raycast = RaycastBuilder.begin(level, entity)
                    .range(32)
                    .checkForBlocks(true)
                    .build();
            if (raycast.getType() == HitResult.Type.ENTITY) {
                target = ((EntityHitResult) raycast).getEntity();
                spawn = target.position();
            } else {
                spawn = Utils.moveToRelativeGroundLevel(level, raycast.getLocation().subtract(entity.getForward().normalize()).add(0, 2, 0), 5);
            }
        }

        FireflySwarmProjectile fireflies = new FireflySwarmProjectile(level, entity, target, getDamage(spellLevel, entity));
        fireflies.moveTo(spawn.add(0, .5, 0));
        level.addFreshEntity(fireflies);

        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

@Override
    public boolean checkPreCastConditions(Level level, int spellLevel, LivingEntity entity, MagicData playerMagicData) {
        return Utils.preCastTargetHelper(level, entity, playerMagicData, this, 32, .35f);
    }

@Override
    public void tick() {
        if (level.isClientSide) {
            for (int i = 0; i < 2; i++) {
                var motion = Utils.getRandomVec3(.05f).add(this.getDeltaMovement());
                var spawn = Utils.getRandomVec3(.25f);
                level.addParticle(ParticleHelper.FIREFLY, getX() + spawn.x, getY() + this.getBbHeight() * .5f + spawn.z, getZ() + spawn.z, motion.x, motion.y, motion.z);
            }
        }
        super.tick();
        if (this.tickCount > maxLife) {
            this.discard();
        }
    }

protected boolean canHitEntity(Entity target) {
        if (!target.isSpectator() && target.isAlive() && target.isPickable()) {
            Entity owner = this.getOwner();
            return owner != target && !DamageSources.isFriendlyFireBetween(owner, target);
        } else {
            return false;
        }
    }

@Nullable
    public Entity getOwner() {
        if (this.cachedOwner != null && !this.cachedOwner.isRemoved()) {
            return this.cachedOwner;
        } else if (this.ownerUUID != null && this.level instanceof ServerLevel) {
            this.cachedOwner = ((ServerLevel) this.level).getEntity(this.ownerUUID);
            return this.cachedOwner;
        } else {
            return null;
        }
    }

